@js:
var FULL = {layout_flexGrow:1, layout_flexBasisPercent:1};
var W2 = {layout_flexGrow:1, layout_flexBasisPercent:0.47};
var BASE = 'https://uxxtv.com';
var CID = {'小说':2,'有声':3,'漫画':4,'视频':1};
var ICON = {'小说':'📖','有声':'🎧','漫画':'🖼','视频':'🎬'};

// 【核心修复】使用 getVariable() 读取并解析
var mode = '小说';
try {
    var savedStr = source.getVariable();
    if (savedStr) {
        var savedObj = JSON.parse(savedStr);
        if (savedObj && savedObj.mode && CID[savedObj.mode]) {
            mode = savedObj.mode;
        }
    }
} catch(e) {}

var arr = [];
arr.push({title:'当前模式：' + mode, type:'button', style:FULL});

var KS = ['小说','有声','漫画','视频'];
for (var i = 0; i < KS.length; i++) {
    var nm = KS[i];
    var t = (nm === mode ? '✅ ' : '') + ICON[nm] + ' ' + nm;

    // 【核心修复】使用 setVariable() 保存 JSON 字符串
    var a = "source.setVariable(JSON.stringify({mode:'" + nm + "'})); java.toast('已切换至 " + nm + "'); java.refreshExplore();";

    arr.push({title: t, type: 'button', action: a, style: W2});
}

arr.push({title:'关键字', type:'text', default:'', style:FULL});
arr.push({title:'🔍 搜索', type:'button', action:"var k=infoMap['关键字'];if(!k){java.toast('请输入关键字');}else{java.searchBook(k,source);}", style:FULL});
arr.push({title:'查看全部【' + mode + '】', url: BASE + '/type/' + CID[mode] + '/{{page}}.html?uxt=' + CID[mode], style:FULL});

JSON.stringify(arr);

