@js:(function(){
var bk=(typeof book!=='undefined'&&book)?book:{};
var bu=String(baseUrl||'')+'|'+String(bk.bookUrl||'')+'|'+String(bk.type||'');
var m=bu.match(/[?&]uxt=([1-4])/);
var t=m?m[1]:'';
if(!t){
var kd=String(bk.kind||'')+String(bk.name||'');
if(kd.indexOf('有声')>=0){t='3';}
else if(kd.indexOf('漫画')>=0){t='4';}
else if(kd.indexOf('视频')>=0){t='1';}
else if(kd.indexOf('小说')>=0){t='2';}
}
if(!t){
var ty=Number(bk.type||0);
t=(ty===4)?'1':((ty===32)?'3':((ty===64)?'4':'2'));
}
var Q=String.fromCharCode(34);
var CFG=','+'{'+Q+'headers'+Q+':'+'{'+Q+'Referer'+Q+':'+Q+'https://uxxtv.com/'+Q+'}'+'}'
var d=String(src||'');
var ajax=function(u){
var h='';
try{h=String(java.ajax(u));}catch(e){}
if(!h||h.length<30||h.indexOf('Access denied')>=0){
try{h=String(java.ajax(u+CFG));}catch(e2){}
}
return h;
};
if(t==='1'){
var mv=d.match(/(https?:)?\/\/[^"'<>\s]+?\.m3u8[^"'<>\s]*/);
if(!mv){return '';}
var u1=mv[0];
return (u1.indexOf('//')===0)?('https:'+u1):u1;
}
if(t==='3'){
var ma=d.match(/<audio[^>]*\ssrc="([^"]+)"/);
if(ma){return ma[1];}
var ma2=d.match(/src="(https?:[^"]+?\.(?:mp3|m4a|aac)[^"]*)"/);
return ma2?ma2[1]:'';
}
if(t==='4'){
var hm=d.match(/uxxhmapi\.php\?([^"'<>\s]+)/);
if(!hm){return '';}
var hc=ajax('https://uxxtv.com/uxxhmapi.php?'+hm[1]);
if(!hc){return '';}
var imgs=hc.match(/<img[^>]+>/g)||[];
var oi=[];
for(var i=0;i<imgs.length;i++){
var s=imgs[i].match(/(?:data-src|src)="([^"]+)"/);
if(s&&s[1].indexOf('data:')<0&&s[1].indexOf('javascript:')<0){oi.push('<img src="'+s[1]+'">');}
}
return oi.join('\n');
}
var gc=d.match(/_getcontent\.php\?([^"'<>\s]+)/);
if(!gc){return '';}
var hg=ajax('https://uxxtv.com/_getcontent.php?'+gc[1]);
if(!hg){return '';}
var ps=hg.split('<script');
var keep=ps[0];
for(var j=1;j<ps.length;j++){
var e2=ps[j].indexOf('</script>');
keep+=(e2>=0)?ps[j].substring(e2+9):'';
}
var AMP=String.fromCharCode(38);
var QT=String.fromCharCode(34);
var NB=String.fromCharCode(160);
var s2=keep.split('<br>').join('\n').split('<br/>').join('\n').split('<br />').join('\n');
s2=s2.split('</p>').join('\n').split('</div>').join('\n');
s2=s2.replace(/<[^>]+>/g,'');
s2=s2.split(AMP+'nbsp;').join(' ').split(AMP+'amp;').join(AMP).split(AMP+'quot;').join(QT).split(NB).join(' ');
var L=s2.split('\n');
var out=[];
for(var k=0;k<L.length;k++){
var x=L[k].replace(/^[\s\u3000]+|[\s\u3000]+$/g,'');
if(!x){continue;}
if(/uxx\d+\.com|uxxdizhi\.com|永久地址|最新地址|更多精彩|加入收藏/.test(x)){continue;}
out.push('\u3000\u3000'+x);
}
return out.join('\n');
})()
